suppressMessages(devtools::load_all("/Users/mohammedsaqr/Documents/Github/latents", quiet = TRUE)); pdf(NULL); set.seed(7)
lse <- function(v) { m <- max(v); m + log(sum(exp(v - m))) }
softmax <- function(s) exp(s) / sum(exp(s))
dmvn <- function(y, m, V) { U <- chol(V); r <- backsolve(U, y - m, transpose = TRUE); -0.5 * (length(y) * log(2 * pi) + 2 * sum(log(diag(U))) + sum(r^2)) }
warn <- function(expr) withCallingHandlers(expr, warning = function(w) { cat("  [warning ", class(w)[1], "] ", substr(conditionMessage(w), 1, 100), "\n", sep = ""); invokeRestart("muffleWarning") })
N <- 80
d <- do.call(rbind, lapply(1:N, function(i) { m <- sample(4:6, 1); t <- sort(sample(0:7, m)); k <- rbinom(1, 1, .45); b <- rnorm(2, 0, c(1, .35)); x <- rnorm(m); e <- runif(m, .5, 1.5)
  data.frame(id = i, t = t, x = x, e = e, y = c(0, 2.5)[k + 1] + c(.7, -.4)[k + 1] * t + .5 * x + log(e) + b[1] + b[2] * t + rnorm(m, sd = .6)) }))
# 1. One class: diagonal and slope-only vs nlme, intervals numeric (nlme has no offset: outcome shifted by hand)
d$yo <- d$y - log(d$e)
f <- mixture_regression(y ~ t + x + offset(log(e)), d, 1, id = "id", class_level = "group", random = ~ 1 + t, random_diagonal = TRUE, seed = 1, tol = 1e-12)
m <- nlme::lme(yo ~ t + x, random = list(id = nlme::pdDiag(~ 1 + t)), d, method = "ML", control = nlme::lmeControl(opt = "optim", tolerance = 1e-10, msMaxIter = 500))
cat(sprintf("diag: LL %.8f nlme %.8f; k %d\n", f$log_likelihood, logLik(m), f$n_parameters))
f <- mixture_regression(y ~ t + x + offset(log(e)), d, 1, id = "id", class_level = "group", random = ~ 0 + t, seed = 1, tol = 1e-12)
m <- nlme::lme(yo ~ t + x, random = ~ 0 + t | id, d, method = "ML", control = nlme::lmeControl(opt = "optim", tolerance = 1e-10, msMaxIter = 500))
cat(sprintf("slope only: LL %.8f nlme %.8f; k %d\n", f$log_likelihood, logLik(m), f$n_parameters))
f <- mixture_regression(y ~ t + offset(log(e)), d, 1, id = "id", class_level = "group", random = ~ 1 + t, seed = 1, tol = 1e-12)
m <- nlme::lme(yo ~ t, random = ~ 1 + t | id, d, method = "ML", control = nlme::lmeControl(opt = "optim", tolerance = 1e-10, msMaxIter = 500))
r <- as.data.frame(get_results(f, "random")); iv <- nlme::intervals(m, which = "var-cov")$reStruct$id
print(cbind(r[r$parameter != "variance", c("parameter", "term", "estimate", "conf_low", "conf_high")], nlme_low = iv$lower, nlme_est = iv$est., nlme_high = iv$upper))
cat("one-class classes table:\n"); print(as.data.frame(get_results(f, "classes"))[c("class", "share", "share_std_error", "share_conf_low", "share_conf_high", "residual_sd", "residual_sd_std_error")])
print(as.data.frame(parameter_inference(f))[c("block", "class", "term", "estimate", "standard_error", "conf_low", "conf_high")][1:7, ])
# 2. Two classes with common + offset + membership: hand LL and SE by a difference of the score
fc <- mixture_regression(y ~ t + x + offset(log(e)), d, 2, id = "id", class_level = "group", random = ~ 1 + t, common = ~ x, seed = 1, n_starts = 3, tol = 1e-10)
p <- fc$params; G <- .growth_covariances(fc$spec, p)
ll <- sum(vapply(1:N, function(i) { a <- d[d$id == i, ]; Z <- cbind(1, a$t)
  lse(log(softmax(c(p$gamma))) + vapply(1:2, function(k) dmvn(a$y, drop(cbind(1, a$t) %*% p$beta[, k] + a$x * p$common + log(a$e)), Z %*% G[[k]] %*% t(Z) + diag(p$sigma2[k], nrow(a))), 0)) }, 0))
th <- coef(fc); nll <- function(t) -.growth_expectation(fc$spec, fc$stats, .growth_unpack(fc$spec, t, p))$log_likelihood
se_n <- sqrt(diag(solve(numDeriv::hessian(nll, th, method.args = list(d = 1e-3, r = 4)))))
cat(sprintf("common+offset: LL %.9f hand %.9f; k %d; SE vs numDeriv max rel %.2e\n", fc$log_likelihood, ll, fc$n_parameters, max(abs(sqrt(diag(vcov(fc))) / se_n - 1))))
pr <- predict(fc, type = "class_response"); a1 <- which(pr$row == 1)
cat("class_response hand", max(abs(pr$fitted[a1] - (cbind(1, d$t[1]) %*% p$beta + d$x[1] * p$common + log(d$e[1])))), "\n")
# 3. Correlated fit's starts table against its own likelihood
da <- do.call(rbind, lapply(1:70, function(i) { t <- sort(sample(1:8, 5)); k <- rbinom(1, 1, .5) + 1; b <- rnorm(1, 0, .8); W <- exp(-.6 * abs(outer(t, t, "-"))); e <- drop(rnorm(5) %*% chol(W + diag(.2, 5))); data.frame(id = i, t = t, y = c(0, 2)[k] + c(.6, -.3)[k] * t + b + e) }))
fa <- warn(mixture_regression(y ~ t, da, 2, id = "id", class_level = "group", random = "intercept", residual_correlation = "ar", seed = 1, n_starts = 4))
print(as.data.frame(get_results(fa, "starts"))[c("start", "kind", "log_likelihood", "stage", "selected")])
ft <- get_results(fa, "fit"); cat(sprintf("fit LL %.4f; n_best_replicated %d; selected start LL %.4f\n", ft$log_likelihood, ft$n_best_replicated, max(get_results(fa, "starts")$log_likelihood[get_results(fa, "starts")$selected])))
fna <- suppressWarnings(mixture_regression(y ~ t, da, 2, id = "id", class_level = "group", random = "intercept", seed = 1, n_starts = 4))
cat(sprintf("the model without the process LL %.4f\n", fna$log_likelihood))
# 4. Two occasions per person with random intercept and slope: not identified (4 covariance parameters, 3 moments)
pp <- do.call(rbind, lapply(1:150, function(i) { b <- rnorm(1, 0, 1); data.frame(id = i, t = 0:1, y = b + .5 * (0:1) + rnorm(2, sd = .7)) }))
f2 <- warn(mixture_regression(y ~ t, pp, 1, id = "id", class_level = "group", random = ~ 1 + t, seed = 1))
print(as.data.frame(get_results(f2, "random"))[c("parameter", "term", "estimate", "std_error", "boundary")]); print(as.data.frame(get_results(f2, "fit"))[c("n_parameters", "log_likelihood", "random_boundary", "converged")]); print(as.data.frame(get_results(f2, "classes"))[c("residual_sd", "residual_sd_std_error")])
f3 <- warn(mixture_regression(y ~ t, pp, 2, id = "id", class_level = "group", random = ~ 1 + t, seed = 1, n_starts = 3))
print(as.data.frame(get_results(f3, "fit"))[c("n_parameters", "log_likelihood", "random_boundary", "converged")])
# 5. Ordinal numeric categories: observed scale in the fitted table
od <- data.frame(id = rep(1:80, each = 5), x = rnorm(400)); ok <- rep(rbinom(80, 1, .5), each = 5)
od$o <- as.integer(cut(ifelse(ok == 1, 1.5, -1.5) + od$x + rlogis(400), c(-Inf, -1, 1, Inf))) - 1L
fo <- mixture_regression(o ~ x, od, 2, family = "ordinal", id = "id", class_level = "group", seed = 1, n_starts = 3)
ftab <- as.data.frame(get_results(fo, "fitted")); cat("data values", sort(unique(od$o)), "; `observed` values", sort(unique(ftab$observed)), "; range fitted", range(ftab$fitted), "\n")
cat("predict response", range(predict(fo)$fitted), "\n")
print(as.data.frame(fo)[c("class","term","estimate","exp_estimate","p_adjusted")])
# 6. Weighted duplication in each regression nesting (coefficient equality, unit-normalised weights)
gd <- data.frame(g = rep(1:40, each = 6), x = rnorm(240)); gc <- rbinom(240, 1, rep(rbeta(40, 1, 1), each = 6))
gd$y <- ifelse(gc == 1, 2 + gd$x, -1 - gd$x) + rnorm(240, sd = .7); gd$w <- rep(sample(1:2, 40, TRUE), each = 6)
du <- do.call(rbind, lapply(1:40, function(j) { a <- gd[gd$g == j, ]; do.call(rbind, lapply(seq_len(a$w[1]), function(r) transform(a, g = j * 10 + r))) }))
cmp <- function(lbl, ...) { a <- mixture_regression(y ~ x, gd, 2, id = "g", weights = "w", seed = 1, n_starts = 3, tol = 1e-11, ...); b <- mixture_regression(y ~ x, du, 2, id = "g", seed = 1, n_starts = 3, tol = 1e-11, ...)
  ca <- coef(a); cb <- coef(b); cat(sprintf("%-14s max coef diff %.2e  LL scale check %.8f\n", lbl, max(abs(ca - cb)), a$log_likelihood / b$log_likelihood - sum(1:40 %in% 1:40) / sum(gd$w[seq(1, 240, 6)]))) }
cmp("group", class_level = "group"); cmp("two-level", n_group_classes = 2); cmp("observation", class_level = "observation")
